import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1787092618000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>RUSTPAD_URL</code></td><td>yes</td><td>—</td><td>Base URL of the Rustpad instance</td></tr><tr><td><code>RUSTPAD_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the read tools</td></tr><tr><td><code>RUSTPAD_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates, scoped</td></tr></tbody></table><h2 id="rustpad-url" tabindex="-1">RUSTPAD_URL <a class="header-anchor" href="#rustpad-url" aria-label="Permalink to “RUSTPAD_URL”">​</a></h2><p>One URL for the HTTP API, the WebSocket endpoint and the share links in tool results. Validated on start: <code>http:</code>/<code>https:</code> only, no embedded credentials, no query or fragment; trailing slashes are stripped. Plain <code>http</code> to a non-local host logs a warning — pad content would travel unencrypted. Without the variable the server still starts, lists its tools, and fails every call with setup instructions (so registries and inspectors can introspect it).</p><h2 id="rustpad-read-only" tabindex="-1">RUSTPAD_READ_ONLY <a class="header-anchor" href="#rustpad-read-only" aria-label="Permalink to “RUSTPAD_READ_ONLY”">​</a></h2><p>Compared against exactly the string <code>true</code>. When active, the five write tools are not registered at all — the connection never advertises them.</p><h2 id="rustpad-insecure-tls" tabindex="-1">RUSTPAD_INSECURE_TLS <a class="header-anchor" href="#rustpad-insecure-tls" aria-label="Permalink to “RUSTPAD_INSECURE_TLS”">​</a></h2><p>Compared against exactly the string <code>true</code>. Disables certificate validation for the configured connection only, via a dedicated dispatcher — never process-wide. The server prints a banner on start when this is active.</p><p>There are no secrets: Rustpad has no authentication, and this server therefore handles no tokens or passwords at all.</p>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};